 * @example
 * // Is 27 September 2014 Saturday?
 * const result = isSaturday(new Date(2014, 8, 27))
 * //=> true
 */
export function isSaturday<DateType extends Date>(
  date: DateType | number | string,
): boolean {
  return toDate(date).getDay() === 6;
}

