 */
export function differenceInCalendarISOWeekYears<DateType extends Date>(
  dateLeft: DateType | number | string,
  dateRight: DateType | number | string,
): number {
  return getISOWeekYear(dateLeft) - getISOWeekYear(dateRight);
}

