    dstOnly(
      `works across DST start & end in local timezone: ${tz || "(unknown)"}`,
      () => {
        const { start, end } = dstTransitions;
        const HOUR = 1000 * 60 * 60;
        const MINUTE = 1000 * 60;
        function sameTime(t1: Date, t2: Date): boolean {
          return (
            t1.getHours() === t2.getHours() &&
